/* From Uiverse.io by TroyRandall  - Tags: icon, button, switch, like, heart */
/* The switch - the box around the slider */
.__UIV_SCOPE__ .comment-react {
  margin: 0;
  display: flex;
  justify-content: center;
  padding: 5px;
  background-color: #f1f1f1;
  border-radius: 5px;
  scale: 1.5;
  width: 100px;
}

.__UIV_SCOPE__ .comment-react button {
  width: 35px;
  height: 35px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: transparent;
  border: 0;
  outline: none;
}

.__UIV_SCOPE__ .comment-react button:after {
  content: "";
  width: 40px;
  height: 40px;
  position: absolute;
  left: -3px;
  top: -3px;
  background-color: #f5356e;
  border-radius: 50%;
  z-index: 0;
  transform: scale(0);
}

.__UIV_SCOPE__ .comment-react button svg {
  position: relative;
  z-index: 9;
}

.__UIV_SCOPE__ .comment-react button:hover:after {
  animation: ripple 0.6s ease-in-out forwards;
}

.__UIV_SCOPE__ .comment-react button:hover svg {
  fill: #f5356e;
}

.__UIV_SCOPE__ .comment-react button:hover svg path {
  stroke: #f5356e;
  fill: #f5356e;
}

.__UIV_SCOPE__ .comment-react hr {
  width: 80%;
  height: 1px;
  background-color: #dfe1e6;
  margin: auto;
  border: 0;
}

.__UIV_SCOPE__ .comment-react span {
  height: 35px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: auto;
  font-size: 20px;
  font-weight: 600;
  color: #707277;
  padding-right: 10px;
  text-align: center;
}

@keyframes ripple {
  0% {
    transform: scale(0);
    opacity: 0.6;
  }

  100% {
    transform: scale(2);
    opacity: 0;
  }
}
